weights = {1: 2, 2: 5, 3: 4, 4: 8, 5: 7, 6: 1, 7: 8, 8: 7, 9: 5, 10: 5, 11: 9, 12: 1, 13: 7, 14: 3, 15: 1, 16: 6, 17: 10, 18: 8, 19: 8, 20: 8, 21: 8, 22: 6, 23: 2, 24: 9, 25: 5, 26: 6, 27: 4, 28: 2, 29: 10, 30: 8, 31: 7, 32: 5, 33: 9, 34: 6, 35: 5, 36: 5, 37: 3, 38: 1, 39: 6, 40: 9, 41: 1, 42: 9, 43: 9, 44: 3, 45: 7, 46: 2, 47: 8, 48: 8, 49: 4, 50: 1, 51: 10, 52: 5, 53: 9, 54: 7, 55: 8, 56: 8, 57: 2, 58: 4, 59: 5, 60: 5, 61: 1, 62: 6, 63: 2, 64: 8, 65: 7, 66: 10, 67: 8, 68: 4, 69: 10, 70: 5, 71: 4, 72: 10, 73: 4, 74: 1, 75: 5, 76: 8, 77: 2, 78: 5, 79: 2, 80: 7, 81: 5, 82: 4, 83: 3, 84: 6, 85: 7, 86: 10, 87: 5, 88: 2, 89: 9, 90: 7, 91: 8, 92: 1, 93: 4, 94: 8, 95: 9, 96: 5, 97: 9, 98: 9, 99: 4, 100: 9, 101: 3, 102: 3, 103: 7, 104: 7, 105: 2, 106: 9, 107: 2, 108: 9, 109: 1, 110: 8, 111: 8, 112: 8, 113: 7, 114: 5, 115: 8, 116: 3, 117: 8, 118: 6, 119: 5, 120: 6, 121: 6, 122: 1, 123: 2, 124: 3, 125: 2, 126: 5, 127: 7, 128: 7, 129: 5, 130: 9, 131: 6, 132: 1, 133: 8, 134: 6, 135: 7, 136: 6, 137: 6, 138: 1, 139: 6, 140: 8}
if set(values.keys()) != set(items):
    raise ValueError('Missing value data for some items.')
if set(weights.keys()) != set(items):
    raise ValueError('Missing weight data for some items.')
m = gp.Model('shopping_centre_knapsack')
x = m.addVars(items, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((values[i] * x[i] for i in items)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weights[i] * x[i] for i in items)) <= 15, name='weight_limit')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for i in items:
        print(f'x[{i}]: {x[i].X}')
else:
    print(f'Solver status: {m.Status}')